import{_ as r,o as s,c as a,a3 as o}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"UIX Forge","description":"Découvrez UIX Forge, un élément personnalisé puissant qui combine modèles, sparks et styles UIX.","frontmatter":{"title":"UIX Forge","description":"Découvrez UIX Forge, un élément personnalisé puissant qui combine modèles, sparks et styles UIX."},"headers":[],"relativePath":"fr/projects/uix/forge/index.md","filePath":"fr/projects/uix/forge/index.md","lastUpdated":1792849697000}'),t={name:"fr/projects/uix/forge/index.md"};function n(i,e,l,u,d,c){return s(),a("div",null,[...e[0]||(e[0]=[o('<p>UIX Forge crée des éléments Home Assistant avec des modèles dans la configuration qu&#39;il contrôle et des extensions grâce aux <a href="./sparks/">Sparks UIX Forge</a>. À partir de <strong>UIX 9.0.0-beta.0</strong>, la <a href="./forge#layered-configuration">configuration en couches</a> permet de conserver les modèles natifs de l&#39;élément et d&#39;appliquer une surcouche Forge séparée, sans éditeur visuel.</p><p>Forge prend en charge les moules <code>card</code>, <code>badge</code>, <code>row</code>, <code>picture-element</code>, <code>section</code>, <code>footer</code> et <code>card-feature</code>. Les moules intercontextes permettent d&#39;intégrer un type d&#39;élément dans un autre contexte parent, par exemple une carte utilisée comme ligne dans une carte Entités ; consultez les <a href="./forge#cross-context-molds">moules intercontextes</a>. La configuration en couches est disponible pour tous les moules.</p><p>Consultez <a href="./forge">Forge</a> pour la référence complète de la configuration.</p><p>L’aperçu <strong>9.0.0-beta.2</strong> ajoute l’<a href="./forge#visual-editor-cards-and-badges">éditeur visuel de cartes et badges</a>. <code>element_base</code> conserve les réglages et modèles natifs inchangés ; seules les valeurs modifiées par Forge vont dans <code>element</code>, pour tous les moules. Le <code>element_base</code> d’une Foundry est une source native préservée : le générer depuis Export et le conserver lors des modifications. Voir la <a href="./foundries#type-de-foundry-et-editeur-native">règle d’ancrage du type</a>.</p><h2 id="fonderies" tabindex="-1">Fonderies <a class="header-anchor" href="#fonderies" aria-label="Permalink to &quot;Fonderies&quot;">​</a></h2><p>Une <strong>fonderie</strong> est une configuration UIX Forge réutilisable. Elle permet de définir une seule fois des fragments <code>forge</code>, <code>element</code> et <code>uix</code> pour plusieurs cartes. À partir de UIX 9.0.0-beta.0, elle peut aussi fournir <code>element_base</code> : une base résolue active la configuration en couches. <code>element_disabled_paths</code> reste local à l&#39;instance Forge qui utilise la fonderie.</p><p>Consultez <a href="./foundries">Fonderies</a> pour un guide complet sur la fusion, les fonderies imbriquées et leur gestion dans les options de l&#39;intégration.</p><h2 id="sparks" tabindex="-1">Sparks <a class="header-anchor" href="#sparks" aria-label="Permalink to &quot;Sparks&quot;">​</a></h2><p>Les Sparks sont des comportements optionnels ajoutés à la liste <code>forge.sparks</code>. Chaque Spark possède une clé <code>type</code> et ses propres options.</p><p>Sparks disponibles :</p><ul><li>💬 <a href="./sparks/tooltip">Infobulle</a> — attache une infobulle stylisée à tout élément créé.</li><li>:material-button-cursor: <a href="./sparks/button">Bouton</a> — attache un bouton stylisé (<code>ha-button</code>) avec actions avant ou après un élément.</li><li>🏷️ <a href="./sparks/attribute">Attribut</a> — ajoute, remplace ou supprime un attribut d&#39;un élément.</li><li>⚡ <a href="./sparks/event">Événement</a> — reçoit des événements DOM d&#39;actions <code>fire-dom-event</code> et expose leurs données comme variables de modèle.</li><li>⭐ <a href="./sparks/tile-icon">Icône Tile</a> — insère un élément <code>ha-tile-icon</code> avant ou après un élément.</li><li>🛡️ <a href="./sparks/state-badge">Badge d&#39;état</a> — insère un élément <code>state-badge</code> avant ou après un élément.</li><li>:material-grid: <a href="./sparks/grid">Grille</a> — applique une mise en page <strong>CSS Grid</strong> à un conteneur.</li><li>🔍 <a href="./sparks/search">Recherche</a> — recherche des éléments avec un sélecteur CSS et applique des modifications aux éléments trouvés.</li><li>:material-map: <a href="./sparks/map">Carte</a> — préserve la vue de la carte et ajoute des visites, des curseurs d&#39;historique et des filtres d&#39;entités avec des positions de contrôle configurables.</li><li>:material-lock: <a href="./sparks/lock">Verrou</a> — superpose un verrou et bloque l&#39;interaction jusqu&#39;à la saisie d&#39;un PIN, d&#39;une phrase secrète ou d&#39;une confirmation.</li><li>:material-star-four-points-outline: <a href="./sparks/overlay-icon">Icône superposée</a> — superpose une <code>ha-icon</code> ou <code>ha-state-icon</code> à un élément.</li><li>:material-image-outline: <a href="./sparks/background">Arrière-plan</a> — ajoute un calque d&#39;arrière-plan, couleur, image, vidéo ou caméra, derrière un élément.</li><li>:material-palette: <a href="./sparks/theme">Thème</a> — applique un thème Frontend à l&#39;élément créé ou à l&#39;un de ses descendants.</li><li><a href="./sparks/form">Formulaire</a> — formulaire Home Assistant avec actions facultatives d&#39;envoi et d&#39;effacement.</li></ul>',11)])])}const f=r(t,[["render",n]]);export{m as __pageData,f as default};
